llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Cerivastatin, a high-transfer analogue, has an absolute oral bioavailability of 60% (90% CI 51-70%) in healthy young men in a randomized crossover IV/oral study, far above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Dabrafenib, a high-transfer analogue containing a fluorinated arylsulfonamide, has an absolute oral bioavailability of 95% in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C80"],
      "claim": "Trovafloxacin, a high-transfer analogue with a difluorophenyl substituent, has a mean absolute oral bioavailability of 87.6% in fasting healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Lumiracoxib, a high-transfer analogue, has an absolute oral bioavailability of 74.0 ± 8.6% in healthy subjects using an IV 13C-labeled reference, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Rufinamide, a high-transfer analogue with a difluorobenzyl group, has an oral bioavailability of 85% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Voriconazole, a high-transfer analogue with a difluorophenyl group, has an absolute oral bioavailability of 83.3 ± 13.9% in subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Safinamide, a high-transfer analogue, has an absolute oral bioavailability of about 95% (90% CI 90-99%) in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Esaxerenone, a high-transfer analogue, has an absolute oral bioavailability of 90.8% in healthy Japanese subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "CC-292, a high-transfer analogue, demonstrated excellent oral bioavailability in a Phase IA human study, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues report absolute oral bioavailability values of 60-95% in humans, consistently far above the 20% threshold. The query's drug-like features and structural similarities, including fluorinated aryl and heteroaromatic/sulfonamide motifs, support a high oral bioavailability prediction.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement is available for the query molecule itself.",
    "Exact first-pass metabolism and transporter effects for the query's methylaminomethyl-pyrrole sulfonamide scaffold are not experimentally characterized.",
    "Most analogue data come from healthy subjects or patients under specific formulation/food conditions, so direct extrapolation to the query is indirect."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

